column13:
SELECT ?rangeId ?energy_sources_labels (AVG(?eng_gen_value) AS ?avg_eng_gen_value)
WHERE {
  orkgr:R153801 orkgp:compareContribution ?contrib.
  ?paper o:has_contribution ?contrib;
         o:has_publication_year ?year.
  BIND(xsd:int(?year) AS ?y).
  VALUES (?rangeId ?min ?max) {
    ("2001-2005" 2001 2005)
    ("2006-2010" 2006 2010)
    ("2011-2015" 2011 2015)
    ("2016-2020" 2016 2020)
  }
  FILTER(?min <= ?y && ?y <= ?max).
  ?contrib o:has_energy_sources ?energy_sources.
  ?energy_sources rdfs:label ?energy_sources_labels;
                  o:has_electricity_generation ?energy_generation.
  ?energy_generation o:has_value ?value.
  BIND(xsd:float(?value) AS ?eng_gen_value).
}
ORDER BY ASC(?rangeId)

